// DLW 连续单孤子；A: (a,p,q)=(2,1,2)，B: (2,4,-3)。
// h 是 y 方向格距，z 是无量纲相位。x,t 导数保持解析。
const cfg = {
  a: 2, p: 1, q: 2,
  h: 1 / 8,
  zMin: -10, zMax: 10, points: 1601,
  levels: 3
};
const { a, p, q, h, zMin, zMax, points, levels } = cfg;
if (![a,p,q,h,zMin,zMax].every(Number.isFinite))
  throw Error("参数必须是有限实数。");
if (!(h > 0 && zMax > zMin) || zMax - zMin > 100)
  throw Error("要求 h>0、zMax>zMin，且相位区间宽度≤100。");
if (!Number.isInteger(points) || points < 41 || points > 10001 ||
    !Number.isInteger(levels) || levels < 1 || levels > 6)
  throw Error("points 应在 41—10001；levels 应在 1—6，均取整数。");
if (h / 2 ** (levels - 1) < 1 / 1024)
  throw Error("最细格距须≥1/1024，以限制浮点消减误差。");
const K = p + q, P = p - a, Q = q + a;
if (!(K > 0) || P === 0 || Q === 0 || !(-P / Q > 0))
  throw Error("单孤子正分支要求 p+q>0，(p-a)(q+a)<0。");
const ell = 1 / P + 1 / Q, Gamma = -P / Q;
const Omega = q*q - p*p, zeta = K * ell;
if (![ell,Gamma,Omega,zeta].every(Number.isFinite))
  throw Error("参数过近谱极点，所得系数非有限。");
const zs = Array.from({length: points}, (_,i) =>
  zMin + (zMax - zMin) * i / (points - 1));
emit({type:"table", columns:["K","ℓ","Γ","ζ = Kℓ","h","相位点数"],
  rows:[[K,ell,Gamma,zeta,h,points]]});

// sigmoid 的解析导数：s^(n)=s(1-s) P_n(s)。
// P_(n+1)=(1-2s)P_n+s(1-s)P_n'；不做数值微分。
const polys = [[1]];
for (let n=1; n<5; n++) {
  const c = polys[n-1];
  polys.push(Array.from({length:c.length+1}, (_,k) =>
    (k+1) * ((c[k] || 0) - (c[k-1] || 0))));
}
function sigmoidJet(z) {
  const e = Math.exp(-Math.abs(z));
  const s = z >= 0 ? 1/(1+e) : e/(1+e);
  const theta = e / (1+e)**2;
  return [s, ...polys.map(c => {
    let value = 0;
    for (let k=c.length-1; k>=0; k--) value = value*s + c[k];
    return theta * value;
  })];
}
function profile(z) {
  const s = sigmoidJet(z), f = sigmoidJet(z + Math.log(Gamma));
  return {
    s, f,
    u: Array.from({length:4}, (_,n) => 2*K*(f[n]-s[n])),
    v: Array.from({length:3}, (_,n) => 2*K*ell*(f[n+1]+s[n+1]))
  };
}
// 两分量二阶主系数，编号对应 DLW 两条物理场方程。
function coefficient(z) {
  const {s,f} = profile(z);
  const d1=f[1]-s[1], d2=f[2]-s[2], d3=f[3]-s[3];
  const B = s[2]**2 + s[1]*s[3];
  return {
    FD: [zeta**3*(f[5]+s[5])/6, zeta**3*(f[5]-s[5])/3],
    SD: [zeta**3*((2*s[5]-f[5])/3+B) - zeta**2*s[3],
         zeta**3*((f[5]+2*s[5])/3+B+2*(d2*d2+d1*d3))
         - zeta**2*s[3]]
  };
}
// 全波形解析上界；不依赖 points 或所选相位区间。
const Z = Math.abs(zeta);
const bounds = {
  FD: [Z**3/12, Z**3/6],
  SD: [251*Z**3/864 + Z**2/8, 59*Z**3/96 + Z**2/8]
};
// 连续解代入有限 h 的 SD/FD 方程；第一式在交错中点求值。
function residual(z, hh, scheme) {
  const cache = new Map();
  function node(j) {
    if (cache.has(j)) return cache.get(j);
    const c=profile(z+ell*hh*j), plus=profile(z+ell*hh*(j+1));
    const minus=profile(z+ell*hh*(j-1));
    const D=c.v.map((_,n) => (plus.u[n]-minus.u[n])/(2*hh));
    const W=c.v.map((v,n) => v-D[n]);
    const Ax=K*(c.u[0]+2*a)*c.u[1];
    const Hx=Ax + (scheme==="SD" ? hh*hh*K*(W[0]/16-1/4)*W[1] : 0);
    const out={...c,D,W,Ax,Hx}; cache.set(j,out); return out;
  }
  const plus=node(1/2), minus=node(-1/2), c=node(0);
  let r1=Omega*(plus.u[1]-minus.u[1])/hh+(plus.Hx-minus.Hx)/hh;
  r1 += K*K*(scheme==="SD"
    ? (plus.u[2]-minus.u[2])/hh+(plus.W[2]+minus.W[2])/2
    : (plus.v[2]+minus.v[2])/2);
  let r2=Omega*c.v[1];
  if (scheme==="SD") {
    const pp=node(1), mm=node(-1);
    r2 += (pp.Hx-mm.Hx)/(2*hh)
      + K*(c.u[1]*c.W[0]+(c.u[0]+2*a)*c.W[1]-4*c.u[1])
      + K*K*(c.D[2]+(pp.W[2]-2*c.W[2]+mm.W[2])/4);
  } else {
    r2 += K*(c.u[1]*c.v[0]+(c.u[0]+2*a)*c.v[1]-4*c.u[1])
      + K*K*c.D[2];
  }
  return [r1,r2];
}
emit({type:"text",text:"已定义解析单孤子、二阶主系数、统一上界及有限 h 方程残差。SDR 的理想半离散残差与 SD 相同。"});

// 同一相位网格比较：R_h / h² → τ；采样最大值不当作连续上界。
const tau = {SD:[[],[]], FD:[[],[]]};
let continuumDefect=0;
for (const z of zs) {
  const t=coefficient(z), {u,v}=profile(z), b=u[0]+2*a;
  for (const S of ["SD","FD"]) for (let i=0;i<2;i++) tau[S][i].push(t[S][i]);
  const terms1=[ell*Omega*u[2], K*K*v[2], K*ell*(u[1]*u[1]+b*u[2])];
  const terms2=[Omega*v[1], K*K*ell*u[3], K*(u[1]*v[0]+b*v[1]-4*u[1])];
  for (const terms of [terms1,terms2]) continuumDefect=Math.max(continuumDefect,
    Math.abs(terms.reduce((x,y)=>x+y,0))/(1+terms.reduce((x,y)=>x+Math.abs(y),0)));
}
if (continuumDefect > 1e-10) throw Error("连续 DLW 方程核对失败，请检查剖面或谱参数。");
const maxAbs = arr => Math.max(...arr.map(Math.abs));
const coeffRows=[];
for (const S of ["SD","FD"]) for (let i=0;i<2;i++) {
  const sampled=maxAbs(tau[S][i]);
  if (!Number.isFinite(sampled) || sampled > bounds[S][i]*(1+1e-10))
    throw Error(`${S} 第 ${i+1} 式超出解析主系数上界，请检查核心表达式。`);
  coeffRows.push([`${S}${S==="SD" ? " / SDR" : ""} · ${i+1}`,sampled,
    bounds[S][i],h*h*sampled,h*h*bounds[S][i]]);
}
emit({type:"table",columns:["方程","采样 max |τ|","全波形解析上界","采样 h² max |τ|","h² 解析上界"],rows:coeffRows});
const convergence=[], finest={SD:[[],[]],FD:[[],[]]}, previous={};
for (let level=0;level<levels;level++) {
  const hh=h/2**level;
  for (const S of ["SD","FD"]) {
    const values=[[],[]], errors=[[],[]];
    zs.forEach((z,k) => {
      const r=residual(z,hh,S);
      for (let i=0;i<2;i++) {
        const normalized=r[i]/(hh*hh);
        if (!Number.isFinite(normalized)) throw Error("有限 h 残差非有限，请检查参数。");
        values[i].push(normalized); errors[i].push(normalized-tau[S][i][k]);
      }
    });
    for (let i=0;i<2;i++) {
      const key=`${S}${i}`, err=maxAbs(errors[i]);
      const rate=level && err>0 && previous[key]>0 ? Math.log2(previous[key]/err) : null;
      convergence.push([`${S} · ${i+1}`,hh,maxAbs(values[i]),err,rate]);
      previous[key]=err;
      if (level===levels-1) finest[S][i]=values[i];
    }
  }
}
emit({type:"table",columns:["方程","h","采样 max |R_h / h²|","采样 max |R_h / h² − τ|","减半收敛阶"],rows:convergence});
for (let i=0;i<2;i++) emit({type:"series",title:`DLW 第 ${i+1} 式：主系数与有限格距残差`,
  xLabel:"无量纲相位 z",yLabel:"方程残差 / h²",series:[
    {name:"SD / SDR 主系数 τ",x:zs,y:tau.SD[i]},
    {name:"FD 主系数 τ",x:zs,y:tau.FD[i]},
    {name:`SD 有限 h=${h/2**(levels-1)}`,x:zs,y:finest.SD[i],dash:true},
    {name:`FD 有限 h=${h/2**(levels-1)}`,x:zs,y:finest.FD[i],dash:true}
  ]});
emit({type:"text",text:`OK：连续 DLW 方程核对的相对残差为 ${continuumDefect.toExponential(2)}；采样主系数均位于解析上界内。表中收敛阶验证有限 h 残差的二阶主项，未计算有限时间的总场误差。`});
